import assert from 'node:assert/strict';import type {GeneratedBody}from '../../src/core/generators/definition';import facts from './legacy-2017-autumn-am-additions-review.json';
/** Independent, manually reviewed source roles/truths. Does not import a
 * producer, its choices, answer computation, geometry, or explanation helper. */
export function reviewAutumnAmAddition(source:string,b:GeneratedBody,v:number[]){
 assert.equal(v.length,1);const usb=source==='2017h29a-fe-am-11';assert(usb||source==='2017h29a-fe-am-65');const r=(usb?facts.usb.conditions:facts.business.conditions)[v[0]];assert(r);assert.deepEqual(b.prompt,[{type:'paragraph',text:r.stem}]);assert.equal(b.choices.length,4);assert.equal(b.answerParts,undefined);assert.equal(b.partAnswers,undefined);assert.equal(b.contexts,undefined);
 if(usb){b.choices.forEach((xs,i)=>{assert.equal(xs.length,1);const x=xs[0];assert.equal(x.type,'diagram');if(x.type!=='diagram')throw Error('DIAGRAM');assert.deepEqual(x.scene,{kind:'source_figure',profile:'legacy-2017-usb-plug-cross-sections',values:[i]});assert.equal(x.caption,'断面図');assert.equal(x.alt,facts.usb.alts[i]);assert(!/USB|Type|正答|正解|適切/.test(x.alt+x.caption));assert.deepEqual(x.rendererRef,{id:'renderer-source-figures',version:'1.0.0'});});
  const opening=v[0]===0?'USB Type-Cは、横長で両端が丸く、上下に対称な接点配置をもつイの断面である。':'USB Type-Aは、長方形の外郭と下寄りの片に並ぶ四つの接点をもつアの断面である。';
  assert.equal(b.explanation,opening+' Type-Cの上下各十二接点の断面と、Type-Aの四接点で上下非対称な断面を区別する。ウには五つの横並びの接点と段差、エには斜めの両下隅と下向きに並ぶ五つの部分があり、ア・イとは外郭と内部配置が異なる。図は同じ縮尺で描かれていないので、図の幅だけで実物の大小を比べない。');
 }else{assert.deepEqual(b.choices,facts.business.choices.map(text=>[{type:'paragraph',text}]));const starts=['BIは、蓄積したデータを分類・加工・分析し、意思決定を支援する。','BPRは、従来の慣行にとらわれず業務プロセスを抜本的に再構築する。','BPMは、業務の流れの可視化と改善サイクルを通じて継続的に業務を改善する。','EAIは、異なるシステム間を連結し、データやプロセスを統合する。'];assert.equal(b.explanation,starts[v[0]]+' アはデータ分析による意思決定の支援、イは業務プロセスの抜本的な再構築、ウは可視化と改善サイクルによる継続的な改善、エは異なるシステムの連結・統合を説明している。名称を説明へ対応させると、'+facts.business.targets[v[0]]+'には'+'アイウエ'[v[0]]+'だけが該当する。');}
 assert.equal(r.truths.filter(Boolean).length,1);assert.equal(b.correctIndex,r.truths.indexOf(true));return r.truths;
}
type Node={tag:string;attrs:Record<string,string>};
function elements(svg:string):Node[]{return [...svg.matchAll(/<(rect|polygon|path)\b([^>]*?)\/?\s*>/g)].map(m=>({tag:m[1],attrs:Object.fromEntries([...m[2].matchAll(/([\w-]+)="([^"]*)"/g)].map(a=>[a[1],a[2]]))}));}
export function reviewAutumnAmUsbSvg(svg:string,i:number){
 const g=facts.usb.geometry[i];assert(g);assert.match(svg,/viewBox="0 0 180 82"/);assert.match(svg,/role="img"/);assert(svg.includes('aria-label="'+facts.usb.alts[i]+'"'));assert(svg.includes('<desc>'+facts.usb.alts[i]+'</desc>'));assert(!/USB|Type-|<image|href=/.test(svg));const nodes=elements(svg),part=(p:string)=>nodes.filter(n=>n.attrs['data-part']===p),shell=part('shell');assert.equal(shell.length,1);const {tag,...attributes}=g.shell;assert.equal(shell[0].tag,tag);for(const[k,v]of Object.entries(attributes))assert.equal(shell[0].attrs[k],String(v));
 const cavities=[{tag:'rect',x:18,y:16,width:144,height:44,rx:1},{tag:'rect',x:18,y:18,width:144,height:42,rx:13},{tag:'polygon',points:'18,16 162,16 162,32 150,42 150,60 30,60 30,42 18,32'},{tag:'polygon',points:'18,16 162,16 162,30 152,40 28,40 18,30'}];const c=part('cavity');assert.equal(c.length,1);assert.equal(c[0].tag,cavities[i].tag);for(const[k,v]of Object.entries(cavities[i]).filter(([k])=>k!=='tag'))assert.equal(c[0].attrs[k],String(v));
 const contacts=nodes.filter(n=>n.attrs['data-contact']!==undefined);const expectedCount=i===1?24:(g.contactCount??0);assert.equal(contacts.length,expectedCount);
 if(i===1){for(let row=0;row<2;row++)for(let j=0;j<12;j++){const ns=contacts.filter(n=>n.attrs['data-row']===String(row)&&n.attrs['data-contact']===String(j));assert.equal(ns.length,1);assert.equal(ns[0].tag,'rect');for(const[k,v]of Object.entries({x:41+j*8,y:[26,47][row],width:5,height:5}))assert.equal(ns[0].attrs[k],String(v));}assert.equal(part('opening')[0].attrs.rx,'11');}
 else for(let j=0;j<contacts.length;j++){const n=contacts[j];assert.equal(n.attrs['data-contact'],String(j));const x=g.contactXs![j];if(i===3){assert.equal(n.tag,'path');assert.equal(n.attrs.d,`M${x},27 V36 H${x+5} V27`);}else{assert.equal(n.tag,'rect');for(const[k,v]of Object.entries({x,y:g.contactY,width:g.contactWidth,height:g.contactHeight}))assert.equal(n.attrs[k],String(v));}}
 const openings=[null,{x:29,y:28,width:122,height:22,rx:11},{x:30,y:30,width:120,height:30},{x:38,y:16,width:104,height:14}];if(openings[i]){assert.equal(part('opening').length,1);for(const[k,v]of Object.entries(openings[i]!))assert.equal(part('opening')[0].attrs[k],String(v));}
 if(i===0){assert.equal(part('lower-piece').length,1);for(const[k,v]of Object.entries({x:18,y:43,width:144,height:17}))assert.equal(part('lower-piece')[0].attrs[k],String(v));assert.equal(nodes.length,7);}
 if(i===1)assert.equal(nodes.length,27);if(i===2)assert.equal(nodes.length,8);
 if(i===3){const posts=part('upper-post'),bumps=part('upper-bump');assert.equal(posts.length,2);assert.equal(bumps.length,3);for(const[j,n]of posts.entries())for(const[k,v]of Object.entries({x:[36,142][j],y:5,width:4,height:7}))assert.equal(n.attrs[k],String(v));for(const[j,n]of bumps.entries())for(const[k,v]of Object.entries({x:[48,88,128][j],y:10,width:4,height:2}))assert.equal(n.attrs[k],String(v));assert.equal(nodes.length,13);}
 return {shape:i,contacts:contacts.length,allGeometryChecked:true};
}
